      sentence = "In the holy Heavenly Sphere, Master's majestic voice fell on my ears with that name that I hadn't heard in a long time. I couldn't help but shddered a bit.",
      next = {33}
    },
    [33] = {
      beijing = 4410,
      dialog = 3,
      mask = "memory",
      music = "22_Despair",
      renwu = "npc",
      sentence = "The former Archangel, Gavin, was once the proudest legend and the most powerful angel in the Heavenly Sphere.",
      next = {34}
    },
    [34] = {
      beijing = 4410,
      dialog = 3,
      mask = "memory",
      music = "22_Despair",
      renwu = "npc",
      sentence = "Like other angels, I secretly admired him, but didn't dare to approach him and would only peek at him behind pillars.",
      next = {35}
    },
    [35] = {
      beijing = 4410,
      dialog = 3,
      mask = "memory",
      music = "22_Despair",
      renwu = "npc",
      sentence = "What I remembered the most about him was watching him from behind as he passed by a valley lily field.",
      next = {36}
    },
    [36] = {
      beijing = 4410,
      dhead = 118,
      dialog = 1,
      mask = "memory",
      music = "22_Despair",
      renming = "$u",
      renwu = "npc",
      sentence = "I am willing to carry out my duty, and go to the human world to judge the sin of Gavin.",
      next = {37}
    },
    [37] = {
      beijing = 4410,
      dhead = 118,
      dialog = 1,
      mask = "memory",
      music = "22_Despair",
      renming = "$u",
      renwu = "npc",
      sentence = "Through my judgment.",
      next = {38}
    },
    [38] = {
      beijing = 4410,
      dialog = 3,
      mask = "memory",
      music = "22_Despair",
      renwu = "npc",
      sentence = "After a moment of silence, I accepted Master's request.",
      next = {39}
    },
    [39] = {
      beijing = 4410,
      dialog = 3,
      mask = "memory",
      music = "22_Despair",
      renwu = "npc",
      sentence = "I didn't believe that Gavin would become a demon, even though he had become a taboo in the Heavenly Sphere and other angels would avoid any mention of him.",
      next = {40}
    },
    [40] = {
      beijing = 4410,
      dialog = 3,
      mask = "memory",
      music = "22_Despair",
      renwu = "npc",
      sentence = "But I wanted to approach him, to confirm with my own eyes whether he had fallen or not.",
      next = {41}
    },
    [41] = {
      beijing = 2506,
      dialog = 3,
      music = "22_Despair",
      renwu = "npc",
      sentence = "But during these six months in the human world, Gavin had been living like an ordinary apprentice. He harmed no humans, nor did he behave in any way that would be considered demonic.",
      next = {42}
    },
    [42] = {
      beijing = 2506,
      dialog = 3,
      music = "22_Despair",
      renwu = "npc",
      sentence = "Over time, I even began to wonder if Gavin had become an ordinary human.",
      next = {43}
    },
    [43] = {
      beijing = 2506,
      dialog = 3,
      music = "22_Despair",
      renwu = "npc",
      sentence = "The tranquil and quiet time was constantly wearing down my determination. Sometimes, I even wished that these ordinary days could last forever.",
      next = {44}
    },
    [44] = {
      beijing = 2506,
      dialog = 3,
      music = "22_Despair",
      renwu = "npc",
      sentence = "So every day, I would leave that judgment to tomorrow.",
      next = {45}
    },
    [45] = {
      beijing = 2506,
      dialog = 3,
      music = "22_Despair",
      renwu = "npc",
      sentence = "But as the mission deadline approached, I knew I couldn't go on like this.",
      next = {46}
    },
    [46] = {
      beijing = 4415,
      dialog = 3,
      music = "22_Despair",
      renwu = "npc",
      sentence = "I sneaked into Gavin's room at night and immediately spotted the young man lying in bed.",
      next = {47}
    },
    [47] = {
      beijing = 4415,
      dialog = 3,
      music = "22_Despair",
      renwu = "npc",
      sentence = "If he was a demon, he would definitely use the power to protect himself when he sensed danger.",
      next = {48}
    },
    [48] = {
      beijing = 4415,
      dialog = 3,
      music = "22_Despair",
      renwu = "npc",
      sentence = "I summoned my angelic sword and placed it against his throat. His eyes were closed and he breaths were steady. It looked as if he was immersed in a sweet dream.",
      next = {49}
    },
    [49] = {
      beijing = 4415,
      dialog = 3,
      music = "22_Despair",
      renwu = "npc",
      sentence = "For a moment, I even felt a bit glad, and thought that perhaps Master was wrong about Gavin.",
      next = {50}
    },
    [50] = {
      beijing = 4415,
      bganim = 2,
      dialog = 3,
      music = "08_Tension",
      renwu = "npc",
      sentence = "Only the next moment, I felt a strong grip on my wrist while an irresistible force knocked the sword out of my hand onto the floor.",
      next = {51}
    },
    [51] = {
