      renwu = "npc",
      role1 = 4113000,
      role2 = 403105,
      role3 = 403203,
      role5 = 4113401,
      roleanim = 1.1,
      sentence = "He looked down at me with a cold and dangerous gaze. With the black-feathered wings arched behind him, he looked very ominous.",
