      renwu = "npc",
      role1 = 4113000,
      role2 = 403110,
      role3 = 403203,
      role5 = 4113401,
      roleanim = 1.1,
      sentence = "He glanced at the sword in the distance before turning his gaze back to me. For some reason, his gaze seemed slightly sorrowful.",
